int main() {
    int N;
    long long K;
    char S[100005];

    scanf("%d %lld", &N, &K);
    scanf("%s", S);

    // Convert S to bit array, S[0] is device 1 (LSB)
    int bits[100005];
    for (int i = 0; i < N; i++) {
        bits[i] = (S[i] == 'B') ? 1 : 0;
    }

    // Add K to the binary number represented by bits[]
    // bits[0] is LSB
    long long carry = K;
    for (int i = 0; i < N && carry > 0; i++) {
        long long sum = bits[i] + carry;
        bits[i] = sum % 2;
        carry = sum / 2;
    }
    // carry beyond N bits is discarded (modulo 2^N)

    // Convert back to string
    for (int i = 0; i < N; i++) {
        S[i] = (bits[i] == 1) ? 'B' : 'A';
    }
    S[N] = '\0';

    printf("%s\n", S);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    long long N, K;
    if (scanf("%lld %lld", &N, &K) != 2) return 0;

    char *S = (char *)malloc((N + 5) * sizeof(char));
    if (!S) return 0;
    scanf("%s", S);

    // Interpret:
    // 'A' -> 0, 'B' -> 1
    // Each ball acts like adding 1 to a binary counter whose bits are device states,
    // with the leftmost device being the least significant bit.
    //
    // For each of the K balls:
    // - If current device is A, it becomes B and stops.
    // - If current device is B, it becomes A and passes to the next device.
    //
    // So after K balls, the state is initial_value + K in binary.

    long long carry = K;
    for (long long i = 0; i < N; i++) {
        long long bit = (S[i] == 'B') ? 1 : 0;
        long long sum = bit + (carry & 1LL);
        if (sum & 1LL) S[i] = 'B';
        else S[i] = 'A';
        carry = (carry >> 1) + (sum >> 1);
    }

    printf("%s\n", S);
    free(S);
    return 0;
}

