int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S;
    long long K;
    cin >> S >> K;

    int n = S.size();
    map<string, long long> seen;
    vector<string> states;

    string cur = S;
    for (long long step = 0; step < K; ++step) {
        if (seen.count(cur)) {
            long long cycle_start = seen[cur];
            long long cycle_len = step - cycle_start;
            long long remaining = K - step;
            long long idx = cycle_start + (remaining % cycle_len);
            cout << states[idx] << "\n";
            return 0;
        }
        seen[cur] = step;
        states.push_back(cur);

        string nxt = cur;
        for (int i = 0; i < n; ++i) {
            if (cur[i] == 'A') {
                if (i + 1 < n) {
                    nxt[i] = 'B';
                    nxt[i+1] = (cur[i+1] == 'A' ? 'B' : 'A');
                } else {
                    nxt[i] = 'B';
                }
            }
        }
        cur = nxt;
    }

    cout << cur << "\n";
    return 0;
}

