#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long K;
    string S;
    cin >> K >> S;

    int n = (int)S.size();
    vector<int> a(n);
    for (int i = 0; i < n; i++) a[i] = (S[i] == 'B');

    // Simulate binary addition of K to the bit string,
    // where A = 0, B = 1, and the leftmost device is the least significant bit.
    int i = 0;
    while (i < n && K > 0) {
        if (K & 1LL) {
            if (a[i] == 0) {
                a[i] = 1;
            } else {
                a[i] = 0;
                int j = i + 1;
                while (j < n && a[j] == 1) {
                    a[j] = 0;
                    j++;
                }
                if (j < n) a[j] = 1;
            }
        }
        K >>= 1;
        i++;
    }

    for (int i = 0; i < n; i++) {
        cout << (a[i] ? 'B' : 'A');
    }
    cout << '\n';
    return 0;
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int K = sc.nextInt();
        String S = sc.next();
        sc.close();

        int n = S.length();
        char[] state = S.toCharArray();

        // We'll process K balls
        for (int ball = 0; ball < K; ball++) {
            int i = 0;
            while (i < n && state[i] == 'A') {
                state[i] = 'B';
                i++;
            }
            if (i < n) {
                // Encountered B: reflect, toggle to A
                state[i] = 'A';
                // Also the previous device (if any) toggles due to reflection
                if (i > 0) {
                    state[i - 1] = (state[i - 1] == 'A') ? 'B' : 'A';
                }
            }
        }

        System.out.println(new String(state));
    }
}

