import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String S = sc.next();
        long K = sc.nextLong();

        int N = S.length();

        // Convert S to BigInteger (S[0] is LSB)
        BigInteger val = BigInteger.ZERO;
        for (int i = 0; i < N; i++) {
            if (S.charAt(i) == 'B') {
                val = val.add(BigInteger.ONE.shiftLeft(i));
            }
        }

        val = val.add(BigInteger.valueOf(K));

        // Convert back to string
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            if (val.testBit(i)) {
                sb.append('B');
            } else {
                sb.append('A');
            }
        }

        System.out.println(sb.toString());
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        long K = fs.nextLong();
        String S = fs.next();

        char[] ans = S.toCharArray();

        // This is the classic "Amidakuji / cylinder devices" process:
        // A device in state 'A' changes to 'B' and passes the ball to the right.
        // A device in state 'B' changes to 'A' and stops the ball.
        //
        // Therefore, processing one ball is exactly adding 1 to a binary number
        // where A = 0 and B = 1, with the leftmost device as the least significant bit.
        //
        // After K balls, we add K to that binary number.

        long carry = K;
        for (int i = 0; i < N; i++) {
            long bit = (ans[i] == 'B') ? 1 : 0;
            long sum = bit + (carry & 1);
            ans[i] = (sum & 1) == 1 ? 'B' : 'A';
            carry = (carry >> 1) + (sum >> 1);
        }

        System.out.println(new String(ans));
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

def solve():
    import sys
    input_data = sys.stdin.read().split()
    S = input_data[0]
    K = int(input_data[1])

    n = len(S)
    # Convert S to number, leftmost is LSB
    num = 0
    for i, c in enumerate(S):
        if c == 'B':
            num |= (1 << i)

    num = (num + K) % (1 << n)

    result = []
    for i in range(n):
        if (num >> i) & 1:
            result.append('B')
        else:
            result.append('A')

    print(''.join(result))

